M="pharm-msk"
BOSS=dict(th="เคสใหญ่: นิ้วโป้งเท้าบวมแดง",en="Boss case: The red, swollen big toe",
case="A 50-year-old man wakes at 3 a.m. with an exquisitely painful, red, swollen first metatarsophalangeal joint after a night of beer and seafood. He takes hydrochlorothiazide. Joint aspirate: needle-shaped, negatively birefringent crystals.",
qs=[
("Diagnosis:",["Acute gout","Pseudogout","Septic arthritis","Rheumatoid arthritis"],0,"Monosodium urate crystals."),
("First-line treatment of the acute flare:",["NSAID, colchicine or glucocorticoid","Allopurinol started at full dose","Probenecid to increase urate excretion","Febuxostat with a uricosuric agent"],0,"e.g., indomethacin. Urate-lowering drugs are not started to treat the flare."),
("Colchicine works by:",["Inhibiting microtubule polymerization in neutrophils","Inhibiting xanthine oxidase in urate production","Inhibiting URAT1 urate reabsorption in the proximal tubule","Inhibiting cyclooxygenase in synovial macrophages"],0,"Binds tubulin. Diarrhea is the commonest side effect."),
("Which medication contributes to his hyperuricemia?",["Hydrochlorothiazide (thiazide diuretic)","Losartan (angiotensin II receptor blocker)","Amlodipine (dihydropyridine CCB)","Lisinopril (ACE inhibitor)"],0,"Thiazides and loop diuretics reduce urate excretion; losartan is uricosuric."),
("Long-term urate-lowering drug of choice:",["Allopurinol","Colchicine","Indomethacin","Prednisone"],0,"Xanthine oxidase inhibitor; titrate to urate < 6 mg/dL."),
("Before starting allopurinol in patients of Han Chinese or Thai descent, test for:",["HLA-B*58:01","HLA-B*57:01","TPMT","G6PD"],0,"Associated with severe cutaneous reactions (SJS/TEN)."),
],pass_=4)
T={
"aa":[("Glucocorticoids inhibit which upstream enzyme?",["Phospholipase A₂","COX-1","5-LOX","Thromboxane synthase"],0,"Blocks arachidonic acid release."),
 ("Aspirin's antiplatelet effect comes from blocking:",["Thromboxane A₂ synthesis","Leukotriene B₄ synthesis","ADP P2Y12 receptor signaling","Glycoprotein IIb/IIIa binding"],0,"Irreversible COX acetylation; platelets cannot make new enzyme."),
 ('A 42-year-old woman with asthma and nasal polyps develops wheezing, rhinorrhea and flushing within an hour of taking ibuprofen. Skin testing for drug allergy is negative. Mechanism of her reaction?', ['Shunting of arachidonate to leukotrienes', 'IgE-mediated mast cell degranulation', 'Excess thromboxane A₂ production', 'Direct β₂-adrenergic receptor blockade'], 0, 'Aspirin-exacerbated respiratory disease: COX blockade diverts arachidonic acid to the 5-lipoxygenase pathway (↑ cysteinyl leukotrienes). It is not IgE-mediated.', 3)],
"apap":[("Acetaminophen differs from NSAIDs because it:",["Has little anti-inflammatory activity","Strongly inhibits platelet aggregation","Causes Reye syndrome","Causes GI ulcers"],0,"Acts mainly centrally."),
 ("Why is acetaminophen preferred for fever in children with viral illness?",["It carries no risk of Reye syndrome","It has stronger anti-inflammatory action","It irreversibly inhibits platelet COX","It shortens the course of viral illness"],0,"Unlike aspirin, which is avoided in children with viral infections."),
 ('A 70-year-old woman with stage 3 chronic kidney disease and a past bleeding duodenal ulcer needs regular analgesia for hip osteoarthritis. The preferred first-line drug acts mainly by:', ['Central COX inhibition, weak peripheral effect', 'Selective peripheral COX-2 inhibition', 'Irreversible acetylation of platelet COX-1', 'Agonism at peripheral μ-opioid receptors'], 0, 'Acetaminophen inhibits COX centrally, so it lacks NSAID renal, GI and antiplatelet effects. Selective COX-2 inhibitors still impair renal prostaglandins.', 3)],
"aspirin":[("Aspirin is avoided in children with viral illness because of:",["Reye syndrome","Gray baby syndrome","Kernicterus","Tooth discoloration"],0,"Fulminant hepatic failure and encephalopathy."),
 ("Low-dose aspirin is used for:",["Secondary prevention of MI and stroke","Antipyretic therapy in febrile children","Urate lowering in chronic gout","Prevention of exercise-induced asthma"],0,"Irreversible platelet COX inhibition."),
 ('A 58-year-old man with acute chest pain and ST elevation in leads II, III and aVF is given 325 mg of chewable aspirin. How long does a single dose impair platelet function?', ['About 7–10 days, the platelet lifespan', 'About 6 hours, until the drug is cleared', 'About 24 hours, until COX is resynthesized', 'About 2–3 days, until hepatic metabolism'], 0, "Aspirin irreversibly acetylates COX-1, and anucleate platelets cannot make new enzyme, so the effect lasts for the platelet's lifespan.", 2)],
"coxib":[("Celecoxib selectively inhibits COX-2, which:",["Spares gastric mucosa and platelets","Impairs platelet aggregation like aspirin","Lowers cardiovascular thrombotic risk","Makes it safe in sulfa allergy"],0,"But ↑ thrombotic risk; sulfa allergy cross-reaction."),
 ("Why do COX-2 inhibitors raise CV risk?",["↓ Prostacyclin, unopposed thromboxane","↑ LDL via hepatic lipid synthesis","Sinus tachycardia from sympathetic drive","Hypokalemia-induced arrhythmia"],0,"Imbalance favors thrombosis."),
 ("A 64-year-old woman with rheumatoid arthritis and a prior upper GI bleed is switched from naproxen to celecoxib. Which adverse effect is increased by this drug's COX-2 selectivity?", ['Myocardial infarction and stroke', 'Upper GI ulceration and bleeding', 'Prolonged bleeding from platelet inhibition', 'Bronchospasm in aspirin-sensitive asthma'], 0, 'COX-2 inhibition lowers endothelial prostacyclin while platelet thromboxane A₂ is spared, favoring thrombosis. Sparing COX-1 reduces, not increases, GI bleeding.', 3)],
"nsaids":[("Renal adverse effect of NSAIDs:",["Afferent arteriolar constriction → ↓ GFR","Efferent arteriolar dilation → ↓ GFR","Nephrogenic DI from ADH resistance","Proximal tubule Fanconi syndrome"],0,"Prostaglandins dilate the afferent arteriole; NSAIDs also cause interstitial nephritis."),
 ("Indomethacin is used to:",["Close a patent ductus arteriosus","Keep the ductus arteriosus open","Reverse warfarin anticoagulation","Stimulate preterm labor contractions"],0,"PGE₁ (alprostadil) keeps it open; indomethacin is also a tocolytic."),
 ('A 72-year-old man with heart failure taking lisinopril and furosemide begins over-the-counter ibuprofen for back pain. Two weeks later his creatinine has risen from 1.1 to 2.3 mg/dL. The newly added drug lowered GFR mainly by:', ['Loss of prostaglandin afferent dilation', 'Efferent dilation from angiotensin blockade', 'Volume depletion from loop diuresis', 'Crystal precipitation in the tubules'], 0, 'NSAIDs block prostaglandins that dilate the afferent arteriole, which is critical when renal perfusion is reduced. Efferent dilation is the contribution of the ACE inhibitor, not the new drug.', 3)],
"dmards":[("Methotrexate in RA requires supplementation with:",["Folic acid","Vitamin K","Iron","Vitamin B6"],0,"Reduces mucositis and cytopenias."),
 ("Hydroxychloroquine requires monitoring for:",["Retinopathy","Pulmonary fibrosis","Hearing loss","Hyperkalemia"],0,"Regular eye examinations."),
 ('A 40-year-old woman with rheumatoid arthritis takes a weekly oral DMARD but skipped her folic acid. She develops oral ulcers and pancytopenia with an MCV of 108 fL. The drug acts by inhibiting:', ['Dihydrofolate reductase', 'Thymidylate synthase directly', 'IMP dehydrogenase', 'Dihydroorotate dehydrogenase'], 0, 'Methotrexate inhibits DHFR, causing megaloblastic cytopenias and mucositis prevented by folate supplementation. Dihydroorotate dehydrogenase is inhibited by leflunomide.', 3)],
"bisph":[("Bisphosphonates work by:",["Inhibiting osteoclast bone resorption","Stimulating osteoblast bone formation","Neutralizing RANKL from osteoblasts","Mimicking intermittent PTH signaling"],0,"Pyrophosphate analogs bind hydroxyapatite and inhibit osteoclast-mediated resorption."),
 ("Oral alendronate is taken upright with water to avoid:",["Pill esophagitis","Hypocalcemia","Osteonecrosis","Hypertension"],0,"Also jaw osteonecrosis and atypical femur fractures."),
 ('A 70-year-old woman takes a weekly oral tablet for osteoporosis, swallowed upright with a full glass of water. After a tooth extraction she has exposed, necrotic mandibular bone that will not heal. The drug acts by:', ['Binding hydroxyapatite and inhibiting osteoclasts', 'Selective estrogen receptor modulation in bone', 'Intermittent activation of the PTH receptor', 'Activation of calcitonin receptors on osteoclasts'], 0, 'Alendronate (a bisphosphonate) binds bone mineral and inhibits osteoclast resorption; osteonecrosis of the jaw is a known adverse effect. Raloxifene is a SERM associated with VTE, not jaw osteonecrosis.', 3)],
"anabolic":[("Teriparatide is a:",["Recombinant PTH 1-34 analog","Monoclonal antibody to RANKL","Monoclonal antibody to sclerostin","Nitrogen-containing bisphosphonate"],0,"Given intermittently, which stimulates osteoblasts; risk of osteosarcoma in rodents."),
 ("Denosumab targets:",["RANKL","Sclerostin","PTH receptor","Estrogen receptor"],0,"Inhibits osteoclast formation; romosozumab targets sclerostin."),
 ('A 74-year-old woman with a T-score of −3.4 has new vertebral fractures despite alendronate. Her physician plans daily subcutaneous injections of a drug that stimulates osteoblasts. Which history would contraindicate this drug?', ['Paget disease of bone or prior skeletal radiation', 'Prior deep vein thrombosis or pulmonary embolism', 'Myocardial infarction or stroke in the past year', 'Hypocalcemia from chronic kidney disease'], 0, 'Teriparatide (PTH analog) carries an osteosarcoma concern, so it is avoided in Paget disease or prior bone radiation. Recent MI/stroke is the caution for romosozumab.', 3)],
"goutchronic":[("Febuxostat acts by:",["Inhibiting xanthine oxidase","Increasing renal urate excretion","Converting urate to allantoin","Blocking IL-1"],0,"Non-purine xanthine oxidase inhibitor."),
 ("Pegloticase works by:",["Converting uric acid to allantoin","Inhibiting xanthine oxidase","Blocking URAT1","Inhibiting tubulin"],0,"Recombinant uricase for refractory gout."),
 ('A 55-year-old kidney transplant recipient taking azathioprine has recurrent gout with tophi. Allopurinol is started. Unless the azathioprine dose is reduced, the combination risks:', ['Bone marrow suppression', 'Severe hyperkalemia', 'Achilles tendon rupture', 'Sensorineural hearing loss'], 0, "Xanthine oxidase inactivates 6-mercaptopurine (azathioprine's active metabolite); allopurinol blocks this, raising levels and causing myelosuppression.", 3)],
"goutacute":[("Which drug should not be started during an acute flare?",["Allopurinol","Indomethacin","Colchicine","Prednisone"],0,"Starting it can prolong the flare; continue it if the patient is already taking it."),
 ("Probenecid is a:",["Uricosuric URAT1 inhibitor","Xanthine oxidase inhibitor","Recombinant uricase enzyme","Microtubule polymerization inhibitor"],0,"Inhibits URAT1 urate reabsorption; risk of uric acid stones."),
 ('A 62-year-old man with an eGFR of 25 mL/min and a recent bleeding gastric ulcer has a hot, swollen knee; aspirate shows negatively birefringent needle-shaped crystals and no organisms. Most appropriate treatment for this flare?', ['Prednisone', 'Indomethacin', 'Allopurinol', 'Probenecid'], 0, 'Acute gout with severe CKD and GI bleeding: glucocorticoids are preferred. NSAIDs are contraindicated here, and urate-lowering drugs do not treat a flare.', 2)],
"tnf":[("Before starting a TNF-α inhibitor, screen for:",["Latent tuberculosis","HLA-B*58:01 allele","G6PD deficiency","TPMT deficiency"],0,"Reactivation of TB is the classic risk."),
 ("Etanercept is a:",["TNF receptor–Fc fusion protein","Chimeric anti-TNF-α monoclonal antibody","IL-6 receptor monoclonal antibody","Oral Janus kinase inhibitor"],0,"Decoy receptor for TNF-α; infliximab, adalimumab, golimumab are anti-TNF antibodies."),
 ('A 45-year-old woman with rheumatoid arthritis started infliximab 4 months ago. She now has fever, night sweats, weight loss and an apical cavitary lesion; sputum shows acid-fast bacilli. Why did this infection develop?', ['Loss of TNF-α needed to maintain granulomas', 'Depletion of CD20-positive B cells', 'Blocked IL-17-driven neutrophil recruitment', 'Impaired complement C5 cleavage'], 0, 'TNF-α is essential for forming and maintaining granulomas that contain M. tuberculosis, so blockade reactivates latent TB. Complement C5 blockade predisposes to Neisseria infection.', 3)],
"psobio":[("Ustekinumab targets:",["p40 subunit of IL-12/IL-23","p19 subunit of IL-23 only","IL-17 receptor A","TNF-α (soluble and membrane)"],0,"Used in psoriasis and Crohn disease; guselkumab targets IL-23 p19."),
 ("Secukinumab targets:",["IL-17A","IL-12/23","IL-6","IgE"],0,"May worsen IBD."),
 ('A 34-year-old man has extensive plaque psoriasis not controlled by topical therapy. He also has Crohn disease. Which biologic should be avoided?', ['Secukinumab', 'Ustekinumab', 'Adalimumab', 'Infliximab'], 0, 'IL-17A inhibitors such as secukinumab can trigger or worsen inflammatory bowel disease. Ustekinumab and anti-TNF agents treat both psoriasis and Crohn disease.', 3)],
"imiq":[("Imiquimod works by:",["Toll-like receptor 7 agonism","Thymidylate synthase inhibition","Calcineurin inhibition in T cells","Microtubule polymerization inhibition"],0,"Stimulates a local immune response; used for genital warts, actinic keratosis and superficial BCC."),
 ("Topical 5-fluorouracil is used for:",["Actinic keratosis","Plaque psoriasis","Nodulocystic acne","Segmental vitiligo"],0,"Thymidylate synthase inhibitor."),
 ('A 27-year-old woman has multiple soft, flesh-colored, cauliflower-like anogenital papules caused by HPV types 6 and 11. She is prescribed a topical immune response modifier that she applies herself. Its mechanism is:', ['Toll-like receptor 7 agonism → IFN-α', 'Thymidylate synthase inhibition', 'Calcineurin inhibition in T cells', 'Binding tubulin to arrest mitosis'], 0, 'Imiquimod activates TLR7, inducing interferon-α and a local antiviral immune response against condylomata. Thymidylate synthase inhibition is 5-fluorouracil.', 3)],
"ra-bio":[("Tocilizumab targets:",["IL-6 receptor","IL-1 receptor","CD20 on B cells","Soluble TNF-α"],0,"Used in RA and giant cell arteritis."),
 ("Abatacept blocks:",["T-cell costimulation (B7–CD28)","IL-1 receptor signaling","Soluble and membrane TNF-α","JAK-STAT cytokine signaling"],0,"CTLA-4–Ig binds B7, preventing CD28 engagement."),
 ('A 74-year-old woman has new temporal headache, jaw claudication and ESR of 92 mm/h. Temporal artery biopsy shows granulomatous inflammation with multinucleated giant cells. A steroid-sparing biologic is added. Its target is:', ['IL-6 receptor', 'CD20 on B cells', 'IL-17A', 'Soluble IgE'], 0, 'Giant cell arteritis: tocilizumab (anti-IL-6 receptor) reduces glucocorticoid exposure. Rituximab targets CD20 and is used in RA and ANCA vasculitis.', 3)],
"skinmap":[("Isotretinoin targets:",["Sebaceous gland activity","Keratinocyte IL-17 signaling","Dermal mast cell degranulation","Melanocyte pigment production"],0,"Oral retinoid for severe nodulocystic acne."),
 ("Calcipotriene in psoriasis is a:",["Vitamin D analog","Retinoid","Steroid","Calcineurin inhibitor"],0,"Inhibits keratinocyte proliferation."),
 ('A 30-year-old man has well-demarcated erythematous plaques with silvery scale on his elbows and knees. He is prescribed topical calcipotriene. Excessive use over large areas can cause:', ['Hypercalcemia', 'Skin atrophy', 'Teratogenicity', 'Hypokalemia'], 0, 'Calcipotriene is a vitamin D analog; extensive application can raise serum calcium. Skin atrophy is the classic effect of potent topical steroids.', 3)],
"tcs":[("Adverse effect of long-term potent topical steroids:",["Skin atrophy and striae","Hyperpigmentation only","Hypertrichosis","Alopecia"],0,"Avoid potent steroids on face and skin folds."),
 ("Topical calcineurin inhibitors (tacrolimus) are useful on the face because:",["They do not cause skin atrophy","They are cheaper than topical steroids","They also act as topical antibiotics","They lighten hyperpigmented skin"],0,"Steroid-sparing for atopic dermatitis."),
 ('A 6-year-old boy has recurrent itchy, lichenified eczema on his eyelids and face. His mother wants to avoid steroid-induced skin thinning. The preferred topical agent acts by:', ['Inhibiting calcineurin and IL-2 transcription', 'Binding glucocorticoid receptors, ↓ NF-κB', 'Inhibiting mTOR and IL-2 signaling', 'Agonism at toll-like receptor 7'], 0, 'Topical tacrolimus/pimecrolimus inhibit calcineurin and do not cause atrophy, making them ideal for facial atopic dermatitis. Glucocorticoid receptor agonism is the steroid mechanism.', 3)],
"acne":[("Isotretinoin is teratogenic and requires:",["Two contraceptive methods + pregnancy tests","A single pregnancy test at baseline only","Only baseline liver function tests","No testing if using oral contraceptives"],0,"iPLEDGE program; also monitor lipids and LFTs."),
 ("Benzoyl peroxide works by:",["Antibacterial action against C. acnes","Suppressing sebaceous gland output","Agonism at nuclear retinoic acid receptors","Blocking androgen receptors in the skin"],0,"Reduces resistance when combined with topical antibiotics."),
 ('A 17-year-old girl has severe nodulocystic acne with scarring despite oral doxycycline and topical retinoids. She is started on oral isotretinoin with two forms of contraception and monthly pregnancy tests. Which other labs must be monitored?', ['Fasting lipids and liver enzymes', 'Serum potassium and creatinine', 'CBC and TPMT enzyme activity', 'Serum calcium and PTH level'], 0, 'Isotretinoin raises triglycerides and can elevate transaminases. TPMT is checked before azathioprine, not retinoids.', 2)],
"psotop":[("Methotrexate in psoriasis requires monitoring for:",["Hepatotoxicity and myelosuppression","Retinopathy and visual field loss","Ototoxicity and vestibular loss","Hypercalcemia and kidney stones"],0,"Weekly dosing with folic acid."),
 ("Acitretin is contraindicated in:",["Women who may become pregnant","Adults older than 65 years","Patients with type 2 diabetes","Patients with nail psoriasis"],0,"Prolonged teratogenicity — pregnancy must be avoided for years after use."),
 ('A 35-year-old woman has a few well-demarcated, silvery-scaled plaques on her elbows and knees covering about 2% of body surface area. No joint symptoms. Most appropriate initial therapy?', ['Topical corticosteroid', 'Oral methotrexate', 'Oral isotretinoin', 'Topical mupirocin ointment'], 0, 'Limited plaque psoriasis is treated first with topical corticosteroids (± a vitamin D analog). Systemic methotrexate is reserved for extensive disease or arthritis.', 2)],
"ra":[("Anchor drug for most patients with early RA:",["Methotrexate","Prednisone alone","Infliximab alone","NSAIDs alone"],0,"Add biologics if inadequate response."),
 ("Low-dose glucocorticoids in RA are used as:",["Bridging therapy until DMARDs take effect","Long-term monotherapy instead of DMARDs","A cure for established joint erosions","Prophylaxis of methotrexate hepatotoxicity"],0,"Minimize duration."),
 ('A 29-year-old woman with seropositive rheumatoid arthritis and active synovitis of the MCP joints plans to conceive within the next year. Which DMARD is most appropriate?', ['Hydroxychloroquine', 'Methotrexate (weekly)', 'Leflunomide (daily)', 'Tofacitinib (twice daily)'], 0, 'Hydroxychloroquine (and sulfasalazine) is compatible with pregnancy. Methotrexate and leflunomide are teratogenic and must be stopped well before conception.', 3)],
"oa-op":[("First-line drug therapy for knee OA:",["Topical NSAID / acetaminophen","Low-dose oral methotrexate","Daily low-dose oral prednisone","Allopurinol titrated to urate"],0,"Plus exercise and weight loss."),
 ("First-line drug for postmenopausal osteoporosis:",["Oral bisphosphonate","Teriparatide injection","Intranasal calcitonin","Estrogen replacement therapy"],0,"Ensure vitamin D and calcium."),
 ('A 67-year-old woman has bilateral knee pain that worsens with activity, morning stiffness under 20 minutes and crepitus. X-rays show asymmetric joint space narrowing and osteophytes. Most appropriate initial drug?', ['Topical diclofenac', 'Oral prednisone', 'Oral methotrexate', 'Hydroxychloroquine'], 0, 'Osteoarthritis: topical NSAIDs (with exercise and weight loss) are first line. Methotrexate and hydroxychloroquine treat inflammatory arthritis, not OA.', 2)],
}
